scwin.disc2 = $c.util.getComponent('disc2');

scwin.disc3 = $c.util.getComponent('disc3');

scwin.disc4 = $c.util.getComponent('disc4');

scwin.divType5 = $c.util.getComponent('divType5');

scwin.dataArr = null;

scwin.dataArr_trust = null;


///////// 2. 초기화 영역 /////////

// 런타임 분기 평가 — 공용 $c.util.evalConds (화면은 조건 바인딩 목록만 보유)
// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = function () {
    let binds = [{ id: "txt_p31", fn: function(){ return ($c.data.readSessionValue("corpUsrTpCd", "session.user.corpUsrTpCd") === '11' || $c.data.readSessionValue("corpUsrTpCd", "session.user.corpUsrTpCd") === '21'); } }];
    $c.util.evalConds(binds);
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        $c.util.getComponent("rd_mktGubun").setValue("1");
        (scwin.rd_mktGubun_onclick ? scwin.rd_mktGubun_onclick() : 0);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil35700.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (§106, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫). onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { $c.data.recvParamData('dma_pageContext'); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil35700.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

