 * @date 2026. 09. 06
 * @param e
 * @returns
 * @hidden N
*/
scwin.rd_mktGubun_onclick = function(e){
    try { let ev = e; let event = ev; let __self = (ev && (ev.element || ev.target || ev.srcElement)) || this; scwin.fn_checkValueMkt() 
