/**
 * @method
 * @name scwin.tx_fn_goTab1
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_goTab1 = async function () {
    const sbmOptions = {
        id: "tx_fn_goTab1",
        method: "post",
        action: "listFee.do",
        ref: "dma_goTab1Req",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: "jldfil35700.tx_fn_goTab1" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) { await $c.win.alert(res.responseJSON.message); }
        return res;
    }
    return res;
};


