/**
 * @method
 * @name scwin.fn_taxCalc_trust
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.fn_taxCalc_trust = async function () {
    scwin.dataArr_trust = new Array();
    let calc_trust = null;
    scwin.dataArr_trust[0] = { issueCode: $c.util.getComponent("ipt_issueCode").getValue(), trust_count: $c.util.getComponent("ipt_trustCount").getValue(), trust_comm: $c.util.getComponent("ipt_commission").getValue() };
    scwin.dataArr_trust[1] = { issueCode: $c.util.getComponent("ipt_issueCode_r1").getValue(), trust_count: $c.util.getComponent("ipt_trustCount_r1").getValue(), trust_comm: $c.util.getComponent("ipt_commission_r1").getValue() };
    scwin.dataArr_trust[2] = { issueCode: $c.util.getComponent("ipt_issueCode_r2").getValue(), trust_count: $c.util.getComponent("ipt_trustCount_r2").getValue(), trust_comm: $c.util.getComponent("ipt_commission_r2").getValue() };
    scwin.dataArr_trust[3] = { issueCode: $c.util.getComponent("ipt_issueCode_r3").getValue(), trust_count: $c.util.getComponent("ipt_trustCount_r3").getValue(), trust_comm: $c.util.getComponent("ipt_commission_r3").getValue() };
    scwin.dataArr_trust[4] = { issueCode: $c.util.getComponent("ipt_issueCode_r4").getValue(), trust_count: $c.util.getComponent("ipt_trustCount_r4").getValue(), trust_comm: $c.util.getComponent("ipt_commission_r4").getValue() };
    scwin.dataArr_trust[5] = { issueCode: $c.util.getComponent("ipt_issueCode_r5").getValue(), trust_count: $c.util.getComponent("ipt_trustCount_r5").getValue(), trust_comm: $c.util.getComponent("ipt_commission_r5").getValue() };
    scwin.dataArr_trust[6] = { issueCode: $c.util.getComponent("ipt_issueCode_r6").getValue(), trust_count: $c.util.getComponent("ipt_trustCount_r6").getValue(), trust_comm: $c.util.getComponent("ipt_commission_r6").getValue() };
    scwin.dataArr_trust[7] = { issueCode: $c.util.getComponent("ipt_issueCode_r7").getValue(), trust_count: $c.util.getComponent("ipt_trustCount_r7").getValue(), trust_comm: $c.util.getComponent("ipt_commission_r7").getValue() };
    scwin.dataArr_trust[8] = { issueCode: $c.util.getComponent("ipt_issueCode_r8").getValue(), trust_count: $c.util.getComponent("ipt_trustCount_r8").getValue(), trust_comm: $c.util.getComponent("ipt_commission_r8").getValue() };
    scwin.dataArr_trust[9] = { issueCode: $c.util.getComponent("ipt_issueCode_r9").getValue(), trust_count: $c.util.getComponent("ipt_trustCount_r9").getValue(), trust_comm: $c.util.getComponent("ipt_commission_r9").getValue() };
    let tot_list = 0;
    let list_comm_sum = 0;
    let inputFlag = false;
    for (i = 0; i < scwin.dataArr_trust.length; i++) {
        if (scwin.dataArr_trust[i].trust_count !== "") {
            inputFlag = true;
            tot_list = (tot_list) + (parseInt(scwin.delComma(scwin.dataArr_trust[i].trust_count)));
            let rt_rate = "0.0";
            if ($c.util.getComponent('ipt_kk').getValue() === "3") {
                scwin.dataArr_trust[i].trust_comm = Math.floor(rate_comm_elw(parseInt(scwin.delComma(scwin.dataArr_trust[i].trust_count))) / 100) * 100;
            } else {
                scwin.dataArr_trust[i].trust_comm = Math.floor(rate_comm(parseInt(scwin.delComma(scwin.dataArr_trust[i].trust_count))) / 100) * 100;
            }
            list_comm_sum = (list_comm_sum) + (scwin.dataArr_trust[i].trust_comm);
        }
    }
    if (inputFlag) {
        $c.util.getComponent("ipt_commission").setValue(scwin.dataArr_trust[0].trust_comm);
        await scwin.numFormat($c.util.fieldEl('ipt_commission', 'commission_1'));
        $c.util.getComponent("ipt_commission_r1").setValue(scwin.dataArr_trust[1].trust_comm);
        await scwin.numFormat($c.util.fieldEl('ipt_commission_r1', 'commission_2'));
        $c.util.getComponent("ipt_commission_r2").setValue(scwin.dataArr_trust[2].trust_comm);
        await scwin.numFormat($c.util.fieldEl('ipt_commission_r2', 'commission_3'));
        $c.util.getComponent("ipt_commission_r3").setValue(scwin.dataArr_trust[3].trust_comm);
        await scwin.numFormat($c.util.fieldEl('ipt_commission_r3', 'commission_4'));
        $c.util.getComponent("ipt_commission_r4").setValue(scwin.dataArr_trust[4].trust_comm);
        await scwin.numFormat($c.util.fieldEl('ipt_commission_r4', 'commission_5'));
        $c.util.getComponent("ipt_commission_r5").setValue(scwin.dataArr_trust[5].trust_comm);
        await scwin.numFormat($c.util.fieldEl('ipt_commission_r5', 'commission_6'));
        $c.util.getComponent("ipt_commission_r6").setValue(scwin.dataArr_trust[6].trust_comm);
        await scwin.numFormat($c.util.fieldEl('ipt_commission_r6', 'commission_7'));
        $c.util.getComponent("ipt_commission_r7").setValue(scwin.dataArr_trust[7].trust_comm);
