                                    $c.util.getComponent("ipt_listCommSumMin").setValue("83300");
                                } else {
                                    if ($c.util.getComponent("dma_goTab1Req").get("kk") === "3") {
                                        $c.util.getComponent("ipt_listCommSumMin").setValue("100000");
                                    } else {
                                        if ($c.util.getComponent("dma_goTab1Req").get("kk") === "4") {
                                            $c.util.getComponent("ipt_listCommSumMin").setValue("300000");
                                        }
                                    }
                                }
                            }
                        } else {
                            if ($c.util.getComponent("dma_goTab1Req").get("listTp") === "3") {
                                if ($c.util.getComponent("dma_goTab1Req").get("kk") === "1") {
                                    $c.util.getComponent("ipt_listCommSumMin").setValue("2000000");
                                } else {
                                    if ($c.util.getComponent("dma_goTab1Req").get("kk") === "2") {
                                        $c.util.getComponent("ipt_listCommSumMin").setValue("300000");
                                    } else {
                                        if ($c.util.getComponent("dma_goTab1Req").get("kk") === "3") {
                                            $c.util.getComponent("ipt_listCommSumMin").setValue("100000");
                                        } else {
                                            if ($c.util.getComponent("dma_goTab1Req").get("kk") === "4") {
                                                $c.util.getComponent("ipt_listCommSumMin").setValue("300000");
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                    await scwin.numFormat($c.util.fieldEl('ipt_listCommSumMin', 'list_comm_sum_min'));
                } else {
                    if ($c.util.getComponent('ipt_mkt').getValue() === "D") {
                        $c.util.getComponent("ipt_listCommSumMin").setValue("100000");
                        await scwin.numFormat($c.util.fieldEl('ipt_listCommSumMin', 'list_comm_sum_min'));
                    }
                }
            }
        }
        if (list_comm_sum_add !== 0) {
            if ($c.util.getComponent('ipt_mkt').getValue() === "1" && $c.util.getComponent("dma_goTab1Req").get("kk") === "3") {
                if (list_comm_sum_add < 100000) {
                    list_comm_sum_add = "100000";
                }
            } else {
                if ($c.util.getComponent('ipt_mkt').getValue() === "2" && $c.util.getComponent("dma_goTab1Req").get("kk") !== "3") {
                    if (list_comm_sum_add < 50000) {
                        list_comm_sum_add = "50000";
                    }
                } else {
                    if ($c.util.getComponent('ipt_mkt').getValue() === "6") {
                        if (list_comm_sum_add < 50000) {
                            list_comm_sum_add = "50000";
                        }
                    } else {
                        if ($c.util.getComponent('ipt_mkt').getValue() === "D") {
                            if (list_comm_sum_add < 100000) {
                                list_comm_sum_add = "100000";
                            }
                        }
                    }
                }
            }
        }
        list_comm_sum_add = parseInt(list_comm_sum_add / 100) * 100;
        $c.util.getComponent("ipt_listCommSumAdd").setValue(list_comm_sum_add);
        await scwin.numFormat($c.util.fieldEl('ipt_listCommSumAdd', 'list_comm_sum_add'));
    } else {
        await $c.win.alert('계산할 항목을 입력해주세요.');
    }
};


