            rate = 300000;
        } else {
            if (i >= 5000000000.0 && i < 10000000000.0) {
                rate = 700000;
            } else {
                if (i >= 10000000000.0 && i < 15000000000.0) {
                    rate = 1000000;
                } else {
                    if (i >= 15000000000.0 && i < 25000000000.0) {
                        rate = 1200000;
                    } else {
                        if (i >= 25000000000.0 && i < 50000000000.0) {
                            rate = 1300000;
                        } else {
                            if (i >= 50000000000.0 && i < 100000000000.0) {
                                rate = 1400000;
