};


/**
 * @method
 * @name scwin.fn_checkValue
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.fn_checkValue = function () {
    let mkt = "";
    let mathTp = "올림";
    $c.util.getComponent('dma_goTab1Req').set('bkk', $c.util.getComponent('ipt_kk').getValue());
    mkt = $c.util.getComponent('rd_mktGubun').getValue();
    let listTp = "";
    let kk = "";
    if (mkt === "1") {
        listTp = $c.util.getComponent('rd_listTpGubun0').getValue();
        kk = $c.util.getComponent('rd_gubun').getValue();
    } else {
        if (mkt === "2") {
            listTp = $c.util.getComponent('rd_listTpGubun').getValue();
            kk = $c.util.getComponent('rd_gubun2').getValue();
        } else {
            if (mkt === "3") {
                kk = $c.util.getComponent('rd_gubun3').getValue();
                if (kk === 3) {
                    mathTp = "버림";
                }
                scwin.fn_reset();
            } else {
                if (mkt === "6") {
                    kk = $c.util.getComponent("dma_goTab1Req").get("gubun4");
                } else {
                    if (mkt === "D") {
                        listTp = "";
                        kk = $c.util.getComponent('rd_gubun11').getValue();
                    }
                }
            }
        }
    }
    scwin.changeStockType(mkt, kk);
    scwin.changeType(mkt, kk);
    ($c.util.getComponent('mathTp') && $c.util.getComponent('mathTp').setValue) ? $c.util.getComponent('mathTp').setValue(mathTp) : (($c.util.getComponent('mathTp') && $c.util.getComponent('mathTp').setText) ? $c.util.getComponent('mathTp').setText(mathTp) : console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + 'mathTp'));
    $c.util.getComponent('ipt_listTp').setValue(listTp);
    $c.util.getComponent('ipt_kk').setValue(kk);
    if (mkt === "3" && kk === "1") {
        $c.util.getComponent('txt_tdNm4').setLabel("* 상장할 신탁원본액");
    } else {
        if (mkt === "3" && kk === "2") {
            $c.util.getComponent('txt_tdNm4').setLabel("* 발행원본액");
        } else {
            if (mkt === "3" && kk === "3") {
                $c.util.getComponent('txt_tdNm4').setLabel("* 발행총액");
            }
        }
    }
    $c.util.getComponent("ipt_totListAmt").setValue("");
    $c.util.getComponent("ipt_listCommSum").setValue("");
    $c.util.getComponent("ipt_listCommSumMin").setValue("");
    $c.util.getComponent("ipt_listCommSumAdd").setValue("");
};


