                document.getElementsByName(colName)[0].style.backgroundColor = '#ffffff';
                document.getElementsByName(colName)[0].readOnly = false;
                var colName2 = "n_list_amt" + x;
                document.getElementsByName(colName2)[0].readOnly = true;
                document.getElementsByName(colName2)[0].value = "";
            }
        }
    }
};


