        $c.util.getComponent('ipt_listTp').setValue("2");
        $c.util.getComponent("rd_listTpGubun").setValue("2");
        $c.util.getComponent('ipt_kk').setValue("1");
        $c.util.getComponent("rd_gubun2").setValue("1");
