/**
 * @method
 * @name scwin.unformat
 * @author Inswave
 * @date 2026. 09. 06
 * @param obj
 * @returns
 * @hidden N
*/
scwin.unformat = function (obj) {
    let temp = "";
    let n = String(obj.value);
    let len = n.length;
    let pos = 0;
    let ch = '';
    while (pos < len) {
        ch = n.charAt(pos);
        if ($c.util.getComponent('ipt_mkt').getValue() === '2' && $c.util.getComponent('ipt_kk').getValue() === '2') {
            if (((ch >= '0') && (ch <= '9')) || (ch === '-') || (ch === '.')) {
                temp = temp + ch;
            }
        } else {
            if (((ch >= '0') && (ch <= '9')) || (ch === '-')) {
                temp = temp + ch;
            }
        }
        pos = pos + 1;
    }
    obj.value = temp;
    return true;
};


/**
 * @method
 * @name scwin.numFormat
 * @author Inswave
 * @date 2026. 09. 06
 * @param obj
 * @returns
 * @hidden N
*/
scwin.numFormat = async function (obj) {
    if (obj.value !== "" && !scwin.isMinusNum(obj.value)) {
        obj.value = "";
        await $c.win.alert("숫자만 입력가능합니다.");
        obj.focus();
        return;
    }
    scwin.unformat(obj);
    if (obj.value === "") {
        return;
    }
    if (isNaN(obj.value)) {
        obj.value = "";
        return;
    }
    if (Number(obj.value) > 999999999999999 || Number(obj.value) < -999999999999999) {
        obj.value = "";
        await $c.win.alert("입력한 숫자가 범위를 초과하였습니다.");
        obj.focus();
        return;
    }
    let str = Number(obj.value) + "";
    let sMinusChar = "";
    if (Number(obj.value) < 0) {
        str = str.substring(1);
        sMinusChar = "-";
    }
    let tempStr = str;
    let fltStr = "";
    if (str.indexOf(".") > -1) {
        tempStr = str.substr(0, str.indexOf("."));
        fltStr = str.substr(str.indexOf("."));
    }
    let leng = tempStr.length;
    let size = 3;
    let cnt = Math.floor(leng / size);
    let pos = leng % size;
    let result = "";
    if (cnt === 0) {
        obj.value = Number(obj.value);
        return;
    }
    for (let i = cnt; i > 0; i = i - 1) {
        result = "," + tempStr.substr(pos + (i - 1) * size, size) + result;
    }
    if (result !== '') {
        if (pos === 0) {
            obj.value = sMinusChar + result.substring(1) + fltStr;
        } else {
            obj.value = sMinusChar + str.substr(0, pos) + result + fltStr;
        }
    }
    return;
};


/**
